-- Read-only candidate inventory. Recheck the current published release before cleanup.
select c.id canonical_card_id,c.anki_card_id,c.anki_note_id,c.current_version_id,c.is_active,split_part(d.full_name,'::',2) source_branch,(select count(*) from card_canonical_entity_links k where k.canonical_card_id=c.id and k.is_active) active_entity_links,(select count(*) from card_knowledge_links k where k.canonical_card_id=c.id and k.is_active) active_knowledge_links from canonical_cards c join anki_cards a on a.id=c.anki_card_id join anki_decks d on d.id=a.deck_id where not exists(select 1 from anki_deck_release_cards r where r.deck_release_id='7764b632-5622-4f1b-959d-1874908fc46d' and r.inclusion_status='included' and r.canonical_card_id=c.id) order by c.id;
